    15→int main() {
    16→    using namespace reaction;
    17→    using namespace std;
    18→
    19→    // A class representing a single stock
    20→    class Stock {
    21→    public:
    22→        Stock(string name, double price, int shares)
    23→            : name(move(name)),
    24→              currentPrice(var(price).setName(this->name + "_price")),
    25→              sharesHeld(var(shares).setName(this->name + "_shares")) {}
    26→
    27→        // Stock name
    28→        const string name;
    29→
    30→        // Current price (reactive variable)
    31→        Var<double> currentPrice;
    32→
    33→        // Number of shares held (reactive variable)
    34→        Var<int> sharesHeld;
    35→
    36→        // Current position value (computed value)
    37→        Calc<double> value = calc([](auto current, auto shares) {
    38→            return current * shares;
    39→        },
    40→            currentPrice, sharesHeld)
    41→                                 .setName(name + "_value");
    42→    };
    43→
    44→    // Create a portfolio of stocks
    45→    vector<Stock> portfolio = {
    46→        Stock("AAPL", 182.52, 100),
    47→        Stock("MSFT", 407.54, 50),
    48→        Stock("GOOGL", 153.78, 75),
    49→        Stock("AMZN", 177.23, 40)};
    50→
    51→    // Total value of all positions (computed value)
    52→    Calc<double> totalValue = calc([&] {
    53→        double sum = 0.0;
    54→        for (auto &stock : portfolio) {
    55→            sum += stock.value();
    56→        }
    57→        return sum;
    58→    }).setName("total_value");
    59→
    60→    // Cash balance (reactive variable)
    61→    auto cashBalance = var(10000.0).setName("cash_balance");
    62→
    63→    // Total net worth = holdings + cash (computed value)
    64→    Calc<double> netWorth = calc([&] {
    65→        return totalValue() + cashBalance();
    66→    }).setName("net_worth");
    67→
    68→    // Print the current state of the portfolio
    69→    auto printPortfolio = action([&] {
    70→        cout << "\n=== Portfolio Update ===\n";
    71→        cout << fixed << setprecision(2);
    72→
    73→        // Print header
    74→        cout << left << setw(8) << "Stock"
    75→             << right << setw(10) << "Price"
    76→             << setw(10) << "Shares"
    77→             << setw(12) << "Value\n";
    78→        cout << string(40, '-') << "\n";
    79→
    80→        // Print each stock's details
    81→        for (auto &stock : portfolio) {
    82→            cout << left << setw(8) << stock.name
    83→                 << right << setw(10) << stock.currentPrice()
    84→                 << setw(10) << stock.sharesHeld()
    85→                 << setw(12) << stock.value() << "\n";
    86→        }
    87→
    88→        // Print summary info
    89→        cout << string(40, '-') << "\n";
    90→        cout << left << setw(18) << "Total Holdings:"
    91→             << right << setw(20) << totalValue() << "\n";
    92→        cout << left << setw(18) << "Cash Balance:"
    93→             << right << setw(20) << cashBalance() << "\n";
    94→        cout << left << setw(18) << "Net Worth:"
    95→             << right << setw(20) << netWorth() << "\n";
    96→        cout << "=====================================\n";
    97→    });
    98→
    99→    // Market opens - batch update all stock prices
   100→    cout << "\n[Market Open: Updating All Stock Prices]\n";
   101→    {
   102→        auto marketOpenBatch = batch([&] {
   103→            portfolio[0].currentPrice.value(183.25); // AAPL up
   104→            portfolio[1].currentPrice.value(405.80); // MSFT down
   105→            portfolio[2].currentPrice.value(155.45); // GOOGL up
   106→            portfolio[3].currentPrice.value(178.75); // AMZN up
   107→        });
   108→        marketOpenBatch.execute();
   109→    }
   110→
   111→    // Execute trades - batch buy/sell operations
   112→    cout << "\n[Execute Trades: Buy AAPL, Sell MSFT]\n";
   113→    {
   114→        auto tradeBatch = batch([&] {
   115→            // Buy 50 shares of AAPL
   116→            double aaplCost = 183.25 * 50;
   117→            portfolio[0].sharesHeld.value(portfolio[0].sharesHeld() + 50);
   118→            cashBalance.value(cashBalance() - aaplCost);
   119→
   120→            // Sell 20 shares of MSFT
   121→            double msftProceeds = 405.80 * 20;
   122→            portfolio[1].sharesHeld.value(portfolio[1].sharesHeld() - 20);
   123→            cashBalance.value(cashBalance() + msftProceeds);
   124→        });
   125→        tradeBatch.execute();
   126→    }
   127→
   128→    // Market fluctuation - some stock prices change
   129→    cout << "\n[Market Fluctuation: AAPL and GOOGL Price Changes]\n";
   130→    {
   131→        auto fluctuationBatch = batch([&] {
   132→            portfolio[0].currentPrice.value(182.90); // AAPL slightly down
   133→            portfolio[2].currentPrice.value(156.75); // GOOGL continues up
   134→        });
   135→        fluctuationBatch.execute();
   136→    }
   137→
   138→    // Dividend payout - batch update cash balance
   139→    cout << "\n[Dividend Payout: AAPL and MSFT Issue Dividends]\n";
   140→    {
   141→        auto dividendBatch = batch([&] {
   142→            double aaplDividend = 0.24 * portfolio[0].sharesHeld();
   143→            double msftDividend = 0.75 * portfolio[1].sharesHeld();
   144→            cashBalance.value(cashBalance() + aaplDividend + msftDividend);
   145→        });
   146→        dividendBatch.execute();
   147→    }
   148→
   149→    return 0;
   150→}
