   266→/**
   267→ * @brief Test manual batch close functionality
   268→ */
   269→TEST(BatchOperationsTest, TestManualBatchClose) {
   270→    auto var1 = reaction::var(5).setName("var1");
   271→    auto calc1 = reaction::calc([&]() { return var1() * 2; }).setName("calc1");
   272→
   273→    // Create batch
   274→    auto batch = reaction::batch([&]() {
   275→        var1.value(10);
   276→    });
   277→
   278→    // Batch should be active initially
   279→    EXPECT_FALSE(batch.isClosed());
   280→
   281→    // While batch is active, reset should be prevented
   282→    EXPECT_THROW(calc1.reset([&]() { return var1() + 100; }), std::runtime_error);
   283→
   284→    // Manually close the batch
   285→    batch.close();
   286→
   287→    // Batch should now be closed
   288→    EXPECT_TRUE(batch.isClosed());
   289→
   290→    // After manual close, reset should work
   291→    EXPECT_NO_THROW(calc1.reset([&]() { return var1() + 100; }));
   292→    EXPECT_EQ(calc1.get(), 105); // 5 + 100 (var1 wasn't changed by batch constructor)
   293→
   294→    // Calling close multiple times should be safe
   295→    EXPECT_NO_THROW(batch.close());
   296→    EXPECT_TRUE(batch.isClosed());
   297→}
