   349→/**
   350→ * @brief Convenience macros for throwing exceptions with file/line information.
   351→ */
   352→#define REACTION_THROW(ExceptionType, ...) \
   353→    throw ExceptionType(__VA_ARGS__, __FILE__, __LINE__, __FUNCTION__)
   354→
   355→#define REACTION_THROW_DEPENDENCY_CYCLE(sourceName, targetName) \
   356→    REACTION_THROW(DependencyCycleException, sourceName, targetName)
   357→
   358→#define REACTION_THROW_SELF_OBSERVATION(nodeName) \
   359→    REACTION_THROW(SelfObservationException, nodeName)
   360→
   361→#define REACTION_THROW_NULL_POINTER(context) \
   362→    REACTION_THROW(NullPointerAccessException, context)
   363→
   364→#define REACTION_THROW_RESOURCE_NOT_INITIALIZED(resourceType) \
   365→    REACTION_THROW(ResourceNotInitializedException, resourceType)
