    13→/**
    14→ * @brief Optimized throughput benchmark for the Reaction framework in multithreaded scenarios
    15→ *
    16→ * This benchmark addresses issues in the original version:
    17→ * 1. Reduces contention between threads
    18→ * 2. Simulates more realistic application scenarios
    19→ * 3. Separates read and write tests to avoid interference
    20→ */
    21→
    22→// ============================================================================
    23→// Independent data source concurrent read test (no contention)
    24→// ============================================================================
    25→
    26→static void BM_MultiThread_IndependentRead(benchmark::State& state) {
    27→    const int num_threads = state.range(0);
    28→    const int operations_per_thread = 1000;
    29→
    30→    // Each thread has its own data source and computation chain to avoid contention
    31→    std::vector<std::vector<Calc<int>>> thread_calcs(num_threads);
    32→    std::vector<Var<int>> thread_sources;
    33→
    34→    for (int t = 0; t < num_threads; ++t) {
    35→        thread_sources.emplace_back(var(t));
    36→
    37→        // Each thread creates its own independent computation chain
    38→        for (int i = 0; i < 10; ++i) {
    39→            if (i == 0) {
    40→                thread_calcs[t].emplace_back(calc([&thread_sources, t]() {
    41→                    return thread_sources[t]() + 1;
    42→                }));
    43→            } else {
    44→                const int prev_idx = i - 1;
    45→                thread_calcs[t].emplace_back(calc([&thread_calcs, t, prev_idx]() {
    46→                    return thread_calcs[t][prev_idx]() + 1;
    47→                }));
    48→            }
    49→        }
    50→    }
    51→
    52→    std::atomic<long long> total_operations{0};
    53→
    54→    for (auto _ : state) {
    55→        std::vector<std::thread> threads;
    56→        std::barrier sync_point(num_threads + 1);
    57→
    58→        for (int t = 0; t < num_threads; ++t) {
    59→            threads.emplace_back([&, t]() {
    60→                sync_point.arrive_and_wait();
    61→
    62→                for (int op = 0; op < operations_per_thread; ++op) {
    63→                    // Each thread only reads its own computation chain, no contention
    64→                    int result = thread_calcs[t].back().get();
    65→                    benchmark::DoNotOptimize(result);
    66→                }
    67→
    68→                total_operations += operations_per_thread;
    69→            });
    70→        }
    71→
    72→        sync_point.arrive_and_wait();
    73→
    74→        for (auto& thread : threads) {
    75→            thread.join();
    76→        }
    77→    }
    78→
    79→    state.SetItemsProcessed(total_operations.load());
    80→    state.counters["ThreadCount"] = num_threads;
    81→    state.counters["OpsPerSecond"] = benchmark::Counter(
    82→        total_operations.load(), benchmark::Counter::kIsRate);
    83→}
