   141→
   142→static void BM_MultiThread_ProducerConsumer(benchmark::State& state) {
   143→    const int num_threads = state.range(0);
   144→    const int operations_per_thread = 100;
   145→
   146→    // Number of producer threads = num_threads / 2, consumers = the rest
   147→    const int num_producers = std::max(1, num_threads / 2);
   148→    const int num_consumers = num_threads - num_producers;
   149→
   150→    // Create multiple data sources for producers
   151→    std::vector<Var<int>> data_sources;
   152→    std::vector<Calc<int>> data_calcs;
   153→
   154→    for (int i = 0; i < num_producers; ++i) {
   155→        data_sources.emplace_back(var(i));
   156→        data_calcs.emplace_back(calc([&data_sources, i]() {
   157→            return data_sources[i]() + 100;
   158→        }));
   159→    }
   160→
   161→    std::atomic<long long> total_operations{0};
   162→
   163→    for (auto _ : state) {
   164→        std::vector<std::thread> threads;
   165→        std::barrier sync_point(num_threads + 1);
   166→
   167→        // Producer threads
   168→        for (int p = 0; p < num_producers; ++p) {
   169→            threads.emplace_back([&, p]() {
   170→                sync_point.arrive_and_wait();
   171→
   172→                for (int op = 0; op < operations_per_thread; ++op) {
   173→                    data_sources[p].value(data_sources[p].get() + 1);
   174→                }
   175→
   176→                total_operations += operations_per_thread;
   177→            });
   178→        }
   179→
   180→        // Consumer threads
   181→        for (int c = 0; c < num_consumers; ++c) {
   182→            threads.emplace_back([&, c]() {
   183→                sync_point.arrive_and_wait();
   184→
   185→                for (int op = 0; op < operations_per_thread; ++op) {
   186→                    // Consumers poll different data sources
   187→                    int source_idx = (c + op) % data_calcs.size();
   188→                    int result = data_calcs[source_idx].get();
   189→                    benchmark::DoNotOptimize(result);
   190→                }
   191→
   192→                total_operations += operations_per_thread;
   193→            });
   194→        }
   195→
   196→        sync_point.arrive_and_wait();
   197→
   198→        for (auto& thread : threads) {
   199→            thread.join();
   200→        }
   201→    }
   202→
   203→    state.SetItemsProcessed(total_operations.load());
   204→    state.counters["ThreadCount"] = num_threads;
   205→    state.counters["Producers"] = num_producers;
   206→    state.counters["Consumers"] = num_consumers;
   207→    state.counters["OpsPerSecond"] = benchmark::Counter(
   208→        total_operations.load(), benchmark::Counter::kIsRate);
   209→}
