   112→// Test complex dependency scenarios with multiple assignments in a single batch
   113→TEST(BatchOperationsTest, TestComplexDependenciesWithMultipleAssignments) {
   114→    // Create base variables
   115→    auto a = reaction::var(1).setName("a");
   116→    auto b = reaction::var(2).setName("b");
   117→    auto c = reaction::var(3).setName("c");
   118→    auto d = reaction::var(4).setName("d");
   119→
   120→    // Track trigger counts for all computed values
   121→    int triggerCountA = 0, triggerCountB = 0, triggerCountC = 0;
   122→    int triggerCountSum = 0, triggerCountProduct = 0, triggerCountCombined = 0;
   123→    int triggerCountFinal = 0;
   124→
   125→    // Create computed values with complex dependencies
   126→    // A: Depends on a and b
   127→    auto A = reaction::calc([&]() {
   128→        triggerCountA++;
   129→        return a() + b();
   130→    }).setName("A");
   131→
   132→    // B: Depends on b and c (shared dependency with A on b)
   133→    auto B = reaction::calc([&]() {
   134→        triggerCountB++;
   135→        return b() * c();
   136→    }).setName("B");
   137→
   138→    // C: Depends on c and d (shared dependency with B on c)
   139→    auto C = reaction::calc([&]() {
   140→        triggerCountC++;
   141→        return c() + d();
   142→    }).setName("C");
   143→
   144→    // Sum: Depends on A, B, and C (aggregates all intermediates)
   145→    auto Sum = reaction::calc([&]() {
   146→        triggerCountSum++;
   147→        return A() + B() + C();
   148→    }).setName("Sum");
   149→
   150→    // Product: Depends on A and B (shared dependencies with Sum)
   151→    auto Product = reaction::calc([&]() {
   152→        triggerCountProduct++;
   153→        return A() * B();
   154→    }).setName("Product");
   155→
   156→    // Combined: Depends on Sum and Product (shared dependencies through A and B)
   157→    auto Combined = reaction::calc([&]() {
   158→        triggerCountCombined++;
   159→        return Sum() - Product();
   160→    }).setName("Combined");
   161→
   162→    // Final: Depends on Combined and C (shared dependency through C)
   163→    auto Final = reaction::calc([&]() {
   164→        triggerCountFinal++;
   165→        return Combined() * C();
   166→    }).setName("Final");
   167→
   168→    // Precompute initial values
   169→    EXPECT_EQ(A.get(), 3);         // 1+2
   170→    EXPECT_EQ(B.get(), 6);         // 2*3
   171→    EXPECT_EQ(C.get(), 7);         // 3+4
   172→    EXPECT_EQ(Sum.get(), 16);      // 3+6+7
   173→    EXPECT_EQ(Product.get(), 18);  // 3*6
   174→    EXPECT_EQ(Combined.get(), -2); // 16-18
   175→    EXPECT_EQ(Final.get(), -14);   // -2*7
   176→
   177→    // Reset counters
   178→    triggerCountA = triggerCountB = triggerCountC = 0;
   179→    triggerCountSum = triggerCountProduct = triggerCountCombined = 0;
   180→    triggerCountFinal = 0;
   181→
   182→    // Execute batch with multiple assignments
   183→    reaction::batchExecute([&]() {
   184→        a.value(10); // Affects A, then everything that depends on A
   185→        b.value(20); // Affects A and B, then their dependents
   186→        c.value(30); // Affects B and C, then their dependents
   187→        d.value(40); // Affects C, then its dependents
   188→    });
   189→
   190→    // Verify trigger counts (each computed value should trigger only once)
   191→    EXPECT_EQ(triggerCountA, 1);
   192→    EXPECT_EQ(triggerCountB, 1);
   193→    EXPECT_EQ(triggerCountC, 1);
   194→    EXPECT_EQ(triggerCountSum, 1);
   195→    EXPECT_EQ(triggerCountProduct, 1);
   196→    EXPECT_EQ(triggerCountCombined, 1);
   197→    EXPECT_EQ(triggerCountFinal, 1);
   198→
   199→    // Verify final values
   200→    EXPECT_EQ(A.get(), 30);            // 10+20
   201→    EXPECT_EQ(B.get(), 600);           // 20*30
   202→    EXPECT_EQ(C.get(), 70);            // 30+40
   203→    EXPECT_EQ(Sum.get(), 700);         // 30+600+70
   204→    EXPECT_EQ(Product.get(), 18000);   // 30*600
   205→    EXPECT_EQ(Combined.get(), -17300); // 700-18000
   206→    EXPECT_EQ(Final.get(), -17300 * 70);
   207→
   208→    // Additional test: Verify that updating only one variable triggers minimal reactions
   209→    triggerCountA = triggerCountB = triggerCountC = 0;
   210→    triggerCountSum = triggerCountProduct = triggerCountCombined = 0;
   211→    triggerCountFinal = 0;
   212→
   213→    reaction::batchExecute([&]() {
   214→        d.value(50); // Only affects C and its dependents
   215→    });
   216→
   217→    // Verify only affected computations are re-evaluated
   218→    EXPECT_EQ(triggerCountA, 0);        // Unchanged
   219→    EXPECT_EQ(triggerCountB, 0);        // Unchanged
   220→    EXPECT_EQ(triggerCountC, 1);        // Changed
   221→    EXPECT_EQ(triggerCountSum, 1);      // Changed (depends on C)
   222→    EXPECT_EQ(triggerCountProduct, 0);  // Unchanged
   223→    EXPECT_EQ(triggerCountCombined, 1); // Changed (depends on Sum)
   224→    EXPECT_EQ(triggerCountFinal, 1);    // Changed (depends on Combined and C)
   225→
   226→    // Verify updated values
   227→    EXPECT_EQ(C.get(), 80);    // 30+50
   228→    EXPECT_EQ(Sum.get(), 710); // 30+600+80
   229→    EXPECT_EQ(Combined.get(), 710 - 18000);
   230→    EXPECT_EQ(Final.get(), (710 - 18000) * 80);
   231→}
