   299→/**
   300→ * @brief Test complex dependency scenario with batch reset protection
   301→ *
   302→ * This test creates a complex dependency graph and verifies that
   303→ * reset operations are properly prevented during active batch operations.
   304→ */
   305→TEST(BatchOperationsTest, TestComplexDependencyBatchResetProtection) {
   306→    // Create a complex dependency graph:
   307→    // var1 -> calc1 -> calc2 -> calc3
   308→    // var2 -> calc1
   309→    //       -> calc4 -> calc5
   310→    // var3 -> calc4
   311→    //       -> calc6 -> calc7
   312→    // var4 -> calc6
   313→    //       -> calc8 -> calc9 -> calc10
