   321→                } catch (...) {
   322→                }
   323→            }
   324→        }
   325→
   326→        timer.stop();
   327→        result.time_with_cache_ms = timer.elapsed_ms();
   328→    }
   329→
   330→    // Test WITHOUT cache
   331→    {
   332→        SimpleTimer timer;
   333→        timer.start();
   334→
   335→        for (size_t iter = 0; iter < iterations; ++iter) {
   336→            // Force cache invalidation frequently
   337→            if (iter % 20 == 0) {
   338→                BenchmarkObserverGraph::forceCacheInvalidation();
   339→            }
   340→
   341→            size_t var_idx = iter % var_count;
   342→            vars[var_idx].value(static_cast<int>(iter % 1000));
   343→
   344→            size_t simple_idx = iter % simple_calcs.size();
   345→            size_t complex_idx = iter % complex_calcs.size();
   346→
   347→            volatile auto simple_val = simple_calcs[simple_idx].get();
   348→            volatile auto complex_val = complex_calcs[complex_idx].get();
   349→            (void)simple_val;
   350→            (void)complex_val;
   351→
   352→            if (iter % 100 == 0) {
   353→                try {
   354→                    auto temp = create([&complex_calcs, complex_idx]() {
   355→                        return complex_calcs[complex_idx]() * 2;
   356→                    });
   357→                    volatile auto temp_val = temp.get();
   358→                    (void)temp_val;
   359→                } catch (...) {
   360→                }
   361→            }
   362→        }
   363→
   364→        timer.stop();
   365→        result.time_without_cache_ms = timer.elapsed_ms();
   366→    }
   367→
   368→    return result;
   369→}
