   232→
   233→/**
   234→ * @brief Specialization for Void type (maintains original behavior).
   235→ */
   236→template <>
   237→class SBOResource<reaction::Void> : public ObserverNode {
   238→public:
   239→    /**
   240→     * @brief Return default Void value.
   241→     */
   242→    reaction::Void getValue() const noexcept {
   243→        return reaction::Void{};
   244→    }
   245→
   246→    /**
   247→     * @brief Always reports using SBO (no actual storage needed).
   248→     */
