    29→/**
    30→ * @brief Optimized close strategy with enhanced type safety.
    31→ *
    32→ * On invalidation, this strategy closes the reactive source,
    33→ * cutting off its output from the dependency graph.
    34→ */
    35→struct CloseHandle : InvalidationBase<CloseHandle> {
    36→    template <typename Source>
    37→    constexpr void handleInvalidImpl(Source &&source) {
    38→        if constexpr (IsReactSource<std::remove_cvref_t<Source>>) {
    39→            source.close();
    40→        }
    41→    }
    42→};
