    11→// Test close handle for reactive graph cleanup
    12→TEST(InvalidationTest, TestCloseHandle) {
    13→    auto a = reaction::var(1).setName("a");
    14→    auto b = reaction::var(2).setName("b");
    15→
    16→    auto dsB = reaction::calc([](auto aa) { return aa; }, a).setName("dsB");
    17→    auto dsC = reaction::calc([](auto aa) { return aa; }, a).setName("dsC");
    18→    auto dsD = reaction::calc([](auto aa) { return aa; }, a).setName("dsD");
    19→    auto dsE = reaction::calc([](auto aa) { return aa; }, a).setName("dsE");
    20→    auto dsF = reaction::calc([](auto aa) { return aa; }, a).setName("dsF");
    21→    auto dsG = reaction::calc([](auto aa) { return aa; }, a).setName("dsG");
    22→
    23→    {
    24→        auto dsA = reaction::calc<reaction::ChangeTrig, reaction::CloseHandle>([](int aa) { return aa; }, a).setName("dsA");
    25→        dsB.reset([&]() { return a() + dsA(); });
    26→        dsC.reset([&]() { return a() + dsA() + dsB(); });
    27→        dsD.reset([&]() { return dsA() + dsB() + dsC(); });
    28→        dsE.reset([&]() { return dsB() * dsC() + dsD(); });
    29→        dsF.reset([&]() { return a() + b(); });
    30→        dsG.reset([&]() { return dsA() + dsF(); });
    31→    }
    32→
    33→    EXPECT_FALSE(static_cast<bool>(dsB));
    34→    EXPECT_FALSE(static_cast<bool>(dsC));
    35→    EXPECT_FALSE(static_cast<bool>(dsD));
    36→    EXPECT_FALSE(static_cast<bool>(dsE));
    37→    EXPECT_TRUE(static_cast<bool>(dsF));
    38→    EXPECT_FALSE(static_cast<bool>(dsG));
    39→}
