    36→ * @tparam Type The type of the resource to manage.
    37→ */
    38→template <typename Type>
    39→class Resource : public std::conditional_t<memory::SBOTraits<Type>::is_sbo_eligible,
    40→                                           memory::SBOResource<Type>,
    41→                                           ResourceImpl<Type>>
    42→{
    43→private:
    44→    using BaseType = std::conditional_t<memory::SBOTraits<Type>::is_sbo_eligible,
    45→                                        memory::SBOResource<Type>,
    46→                                        ResourceImpl<Type>>;
    47→
    48→public:
    49→    using BaseType::BaseType; // Inherit constructors
    50→
    51→    // Expose whether this instance is using SBO
    52→    [[nodiscard]] bool isUsingSBO() const noexcept {
    53→        if constexpr (memory::SBOTraits<Type>::is_sbo_eligible) {
    54→            return static_cast<const memory::SBOResource<Type> *>(this)->isUsingSBO();
    55→        } else {
