   156→     *
   157→     * @tparam F Operation function type (should take Type& and return bool indicating if changed).
   158→     * @param operation The operation to perform on the value.
   159→     * @param alwaysChanged If true, always consider the operation as changing the value.
   160→     */
   161→    template <typename F>
   162→    void atomicOperation(F &&operation, bool alwaysChanged = false) {
   163→        REACTION_REGISTER_THREAD();
   164→        bool changed = false;
   165→        {
   166→            ConditionalUniqueLock<ConditionalSharedMutex> lock(m_resourceMutex);
   167→            try {
