   239→            .using_sbo = is_sbo_storage,
   240→            .initialized = is_initialized,
   241→            .type_size = sizeof(Type),
   242→            .stack_usage = is_sbo_storage ? sizeof(Type) : 0
   243→        };
   244→    }
   245→
   246→    /**
   247→     * @brief Generic atomic operation helper.
   248→     *
   249→     * @tparam F Operation function type (should take Type& and return bool indicating if changed).
   250→     * @param operation The operation to perform on the value.
   251→     * @param alwaysChanged If true, always consider the operation as changing the value.
   252→     */
   253→    template <typename F>
   254→    void atomicOperation(F &&operation, bool alwaysChanged = false) {
   255→        REACTION_REGISTER_THREAD();
   256→        bool changed = false;
   257→        {
   258→            ConditionalUniqueLock<ConditionalSharedMutex> lock(m_resourceMutex);
   259→            try {
   260→                // Direct access to avoid lock recursion
   261→                if (!is_initialized) {
   262→                    REACTION_THROW_RESOURCE_NOT_INITIALIZED("SBOResource");
   263→                }
   264→
   265→                if (is_sbo_storage) {
   266→                    Type* ptr = reinterpret_cast<Type*>(const_cast<char*>(storage.buffer));
   267→                    changed = operation(*ptr);
   268→                } else {
   269→                    changed = operation(*storage.heap_ptr);
   270→                }
   271→
   272→                if (alwaysChanged) {
   273→                    changed = true;
   274→                }
   275→            } catch (const std::runtime_error&) {
   276→                // Resource not initialized, treat as no change
   277→                changed = false;
   278→            }
   279→        } // Lock is automatically released here
   280→
   281→        // Trigger notifications like ReactImpl does
   282→        if (!g_batch_execute && changed) {
   283→            this->notify(true);
   284→        }
   285→    }
   286→
   287→private:
   288→    /**
   289→     * @brief Initialize storage with given value.
   290→     */
   291→    template<typename T>
   292→    void initializeWith(T&& t) {
   293→        try {
   294→            initializeWithImpl(std::forward<T>(t));
   295→        } catch (...) {
   296→            is_initialized = false;
   297→            is_sbo_storage = false;
   298→            throw;
   299→        }
   300→    }
   301→
   302→    /**
   303→     * @brief Internal initialization implementation.
   304→     */
   305→    template<typename T>
   306→    void initializeWithImpl(T&& t) {
   307→        if constexpr (always_sbo) {
   308→            // Always use SBO for small types
   309→            if (is_initialized && !is_sbo_storage) {
   310→                // Destroy heap_ptr if it was active from a previous state
   311→                storage.heap_ptr.~unique_ptr<Type>();
   312→            } else if (!is_initialized) {
   313→                // First time: destroy the default-constructed heap_ptr
   314→                storage.heap_ptr.~unique_ptr<Type>();
   315→            }
   316→            new(storage.buffer) Type(std::forward<T>(t));
   317→            is_sbo_storage = true;
   318→            is_initialized = true;
   319→        } else if constexpr (conditional_sbo) {
   320→            // Conditional SBO based on stack usage
   321→            StackMonitor::StackGuard<sizeof(Type)> guard;
   322→            if (guard.success()) {
   323→                // Use SBO
   324→                if (is_initialized && !is_sbo_storage) {
   325→                    // Destroy heap_ptr if it was active from a previous state
   326→                    storage.heap_ptr.~unique_ptr<Type>();
   327→                } else if (!is_initialized) {
   328→                    // First time: destroy the default-constructed heap_ptr
   329→                    storage.heap_ptr.~unique_ptr<Type>();
   330→                }
   331→                new(storage.buffer) Type(std::forward<T>(t));
   332→                is_sbo_storage = true;
   333→                is_initialized = true;
   334→            } else {
   335→                // Use heap allocation
   336→                if (is_initialized && is_sbo_storage) {
   337→                    // Destroy buffer content and re-construct heap_ptr
   338→                    reinterpret_cast<Type*>(storage.buffer)->~Type();
   339→                    new(&storage.heap_ptr) std::unique_ptr<Type>();
   340→                }
   341→                // heap_ptr is already available - either from constructor or re-construction above
   342→                storage.heap_ptr = std::make_unique<Type>(std::forward<T>(t));
   343→                is_sbo_storage = false;
   344→                is_initialized = true;
   345→            }
   346→        } else {
   347→            // Force heap allocation
   348→            if (is_initialized && is_sbo_storage) {
   349→                // Destroy buffer content and re-construct heap_ptr
   350→                reinterpret_cast<Type*>(storage.buffer)->~Type();
   351→                new(&storage.heap_ptr) std::unique_ptr<Type>();
   352→            }
   353→            // heap_ptr is already available - either from constructor or re-construction above
   354→            storage.heap_ptr = std::make_unique<Type>(std::forward<T>(t));
   355→            is_sbo_storage = false;
   356→            is_initialized = true;
   357→        }
   358→    }
   359→
   360→    /**
   361→     * @brief Destroy stored object and cleanup.
   362→     */
   363→    void destroy() noexcept {
   364→        if (is_initialized) {
   365→            if (is_sbo_storage) {
   366→                // Destroy the object in buffer
   367→                reinterpret_cast<Type*>(storage.buffer)->~Type();
   368→            } else {
   369→                // Destroy heap_ptr
   370→                storage.heap_ptr.~unique_ptr<Type>();
   371→            }
   372→            is_initialized = false;
   373→            is_sbo_storage = false;
   374→        } else {
   375→            // For uninitialized default-constructed objects, destroy heap_ptr
   376→            storage.heap_ptr.~unique_ptr<Type>();
   377→        }
   378→    }
   379→
   380→protected:
   381→    mutable ConditionalSharedMutex m_resourceMutex; ///< Thread-safe access mutex
   382→};
   383→
   384→} // namespace reaction::memory

