   699→/**
   700→ * @brief Test concurrent increment operations on var<int>
   701→ *
   702→ * This test verifies that multiple threads can safely perform increment operations
   703→ * on a shared var<int> without causing crashes or race conditions.
   704→ * Note: Due to the nature of concurrent operations, exact final values may vary.
   705→ */
   706→TEST(ThreadSafetyTest, VarIncrementConcurrency) {
   707→    std::cout << "=== Var Increment Concurrency Test ===" << std::endl;
   708→
   709→    auto &manager = reaction::ThreadManager::getInstance();
   710→    manager.resetForTesting();
   711→
   712→    // Create a shared integer variable
   713→    auto sharedCounter = reaction::var(0);
   714→
   715→    const int numThreads = 4;
   716→    const int incrementsPerThread = 50; // Reduced to make race conditions more visible
   717→
   718→    std::atomic<int> totalOperationsPerformed{0};
   719→    std::atomic<int> threadsCompleted{0};
   720→    std::atomic<bool> raceDetected{false};
   721→    std::vector<std::thread> threads;
   722→
   723→    // Function for each thread to perform increments
   724→    auto incrementTask = [&](int threadId) {
   725→        try {
   726→            for (int i = 0; i < incrementsPerThread; ++i) {
   727→                // Use atomic increment operation instead of read-modify-write
   728→                ++sharedCounter; // This uses the atomic pre-increment operator
   729→                totalOperationsPerformed++;
   730→            }
   731→            threadsCompleted++;
   732→        } catch (const std::exception &e) {
   733→            std::cout << "Thread " << threadId << " caught exception: " << e.what() << std::endl;
   734→            raceDetected = true;
   735→        } catch (...) {
   736→            std::cout << "Thread " << threadId << " caught unknown exception" << std::endl;
   737→            raceDetected = true;
   738→        }
   739→    };
   740→
   741→    std::cout << "Starting " << numThreads << " threads, each performing "
   742→              << incrementsPerThread << " increments..." << std::endl;
   743→
   744→    // Launch threads
   745→    for (int i = 0; i < numThreads; ++i) {
   746→        threads.emplace_back(incrementTask, i);
   747→    }
   748→
   749→    // Wait for all threads to complete
   750→    for (auto &thread : threads) {
   751→        thread.join();
   752→    }
   753→
   754→    // Check final result
   755→    int finalValue = sharedCounter.get();
   756→
   757→    std::cout << "=== Var Increment Concurrency Test Results ===" << std::endl;
   758→    std::cout << "Total operations performed: " << totalOperationsPerformed.load() << std::endl;
   759→    std::cout << "Expected operations: " << (numThreads * incrementsPerThread) << std::endl;
   760→    std::cout << "Final counter value: " << finalValue << std::endl;
   761→    std::cout << "Threads completed: " << threadsCompleted.load() << std::endl;
   762→    std::cout << "Race conditions detected: " << (raceDetected.load() ? "Yes" : "No") << std::endl;
   763→
   764→    // Verify results - with atomic operations, final value should equal total operations
   765→    EXPECT_EQ(threadsCompleted.load(), numThreads);
   766→    EXPECT_EQ(totalOperationsPerformed.load(), numThreads * incrementsPerThread);
   767→    EXPECT_FALSE(raceDetected.load()) << "Race conditions detected during increment operations";
   768→
   769→    // With atomic increment operations, final value should equal the number of operations
   770→    EXPECT_EQ(finalValue, numThreads * incrementsPerThread) << "Atomic increment should ensure final value equals expected operations";
   771→
   772→    std::cout << "✅ Var increment concurrency test passed" << std::endl;
   773→}
