    50→ * @brief Test automatic enabling of thread safety in multi-threaded mode
    51→ */
    52→TEST(ThreadSafetyTest, MultiThreadAutoEnable) {
    53→    std::cout << "=== Multi-thread Auto-enable Test ===" << std::endl;
    54→
    55→    auto &manager = reaction::ThreadManager::getInstance();
    56→    manager.resetForTesting();
    57→
    58→    // Verify reset worked
    59→    bool initialState = manager.isThreadSafetyEnabled();
    60→    std::cout << "Initial thread safety state: " << (initialState ? "Enabled" : "Disabled") << std::endl;
    61→
    62→    // Create shared variable
    63→    auto sharedVar = reaction::var(0);
    64→
    65→    std::atomic<int> thread1Operations{0};
    66→    std::atomic<int> thread2Operations{0};
    67→    std::atomic<bool> multiThreadDetected{false};
    68→
    69→    // Force thread safety to start in disabled state by making this
    70→    // look like a fresh start. We'll launch worker threads to simulate
    71→    // a multi-threaded application starting fresh.
    72→
    73→    std::atomic<bool> threadSafetyWasEnabled{false};
    74→
    75→    // Thread 1
    76→    std::thread thread1([&]() {
    77→        for (int i = 0; i < 100; ++i) {
    78→            sharedVar.value(i); // This triggers REACTION_REGISTER_THREAD
    79→            thread1Operations++;
    80→            if (i == 50) {
    81→                // Check if thread safety was enabled by this point
    82→                threadSafetyWasEnabled = manager.isThreadSafetyEnabled();
    83→            }
    84→            std::this_thread::sleep_for(std::chrono::microseconds(10));
    85→        }
    86→    });
    87→
    88→    // Thread 2
    89→    std::thread thread2([&]() {
    90→        std::this_thread::sleep_for(std::chrono::milliseconds(1)); // Let thread1 start first
    91→        for (int i = 0; i < 100; ++i) {
    92→            int value = sharedVar.get(); // This triggers REACTION_REGISTER_THREAD
    93→            (void)value;
    94→            thread2Operations++;
    95→            std::this_thread::sleep_for(std::chrono::microseconds(10));
    96→        }
    97→    });
    98→
    99→    thread1.join();
   100→    thread2.join();
   101→
   102→    // Check thread safety state after multi-threading
   103→    bool afterMultiThread = manager.isThreadSafetyEnabled();
   104→    std::cout << "Thread safety state after multi-thread operations: " << (afterMultiThread ? "Enabled" : "Disabled") << std::endl;
   105→    std::cout << "Thread safety was enabled during execution: " << (threadSafetyWasEnabled ? "Yes" : "No") << std::endl;
   106→
   107→    // The test should pass if either:
   108→    // 1. Thread safety was enabled at some point during execution, OR
   109→    // 2. Thread safety is enabled at the end
   110→    // This accounts for the fact that the main thread may already be registered
   111→    bool testPassed = afterMultiThread || threadSafetyWasEnabled.load();
   112→
   113→    EXPECT_TRUE(testPassed) << "Thread safety should be enabled in multi-thread mode (either during or after execution)";
   114→    EXPECT_EQ(thread1Operations.load(), 100);
   115→    EXPECT_EQ(thread2Operations.load(), 100);
   116→
   117→    std::cout << "✅ Multi-thread auto-enable test passed" << std::endl;
   118→}
