   400→/**
   401→ * @brief Test concurrent read operations on shared dependency graph
   402→ *
   403→ * This simpler test only does concurrent reads to check if basic
   404→ * thread safety works without modifications.
   405→ */
   406→TEST(ThreadSafetyTest, SharedDependencyGraphReadOnly) {
   407→    std::cout << "=== Shared Dependency Graph Read-Only Test ===" << std::endl;
   408→
   409→    auto &manager = reaction::ThreadManager::getInstance();
   410→    manager.resetForTesting();
   411→
   412→    std::atomic<int> operationsCompleted{0};
   413→    std::atomic<bool> raceDetected{false};
   414→    std::atomic<int> exceptionCount{0};
   415→
   416→    // Create SHARED variables and expressions
   417→    auto sharedVar1 = reaction::var(42);
   418→    auto sharedVar2 = reaction::var(24);
   419→
   420→    auto sharedExpr1 = reaction::calc([&]() {
   421→        return sharedVar1.get() + sharedVar2.get();
   422→    });
   423→
   424→    auto sharedExpr2 = reaction::calc([&]() {
   425→        return sharedVar1.get() * sharedVar2.get();
   426→    });
   427→
   428→    auto sharedExpr3 = reaction::calc([&]() {
   429→        return sharedExpr1.get() + sharedExpr2.get();
   430→    });
   431→
   432→    // Pre-initialize all expressions to ensure they are calculated before concurrent access
   433→    std::cout << "Pre-initializing expressions..." << std::endl;
   434→    int initVal1 = sharedExpr1.get();
   435→    int initVal2 = sharedExpr2.get();
   436→    int initVal3 = sharedExpr3.get();
   437→    std::cout << "Initial values: expr1=" << initVal1 << ", expr2=" << initVal2 << ", expr3=" << initVal3 << std::endl;
   438→
   439→    // Expected values
   440→    const int EXPECTED_VAL1 = 42 + 24;                       // 66
   441→    const int EXPECTED_VAL2 = 42 * 24;                       // 1008
   442→    const int EXPECTED_VAL3 = EXPECTED_VAL1 + EXPECTED_VAL2; // 1074
   443→
   444→    // Verify initial values are correct
   445→    EXPECT_EQ(initVal1, EXPECTED_VAL1);
   446→    EXPECT_EQ(initVal2, EXPECTED_VAL2);
   447→    EXPECT_EQ(initVal3, EXPECTED_VAL3);
   448→
   449→    const int numThreads = 4;
   450→    const int operationsPerThread = 1000;
   451→
   452→    auto readOnlyOperation = [&](int threadId) {
   453→        try {
   454→            for (int i = 0; i < operationsPerThread; ++i) {
   455→                // Only read operations - focus on thread safety rather than strict consistency
   456→                int val1 = sharedExpr1.get();
   457→                int val2 = sharedExpr2.get();
   458→                int val3 = sharedExpr3.get();
   459→
   460→                // Basic sanity checks - values should be reasonable and positive
   461→                if (val1 < 0 || val2 < 0 || val3 < 0) {
   462→                    std::cout << "Thread " << threadId << ": Negative value detected! "
   463→                              << "expr1=" << val1 << ", expr2=" << val2
   464→                              << ", expr3=" << val3 << std::endl;
   465→                    raceDetected = true;
   466→                }
   467→
   468→                // Check that individual expressions have correct values (most stable)
   469→                if (val1 != EXPECTED_VAL1) {
   470→                    std::cout << "Thread " << threadId << ": expr1 value inconsistency! "
   471→                              << "got=" << val1 << ", expected=" << EXPECTED_VAL1 << std::endl;
   472→                    raceDetected = true;
   473→                }
