    71→// Test SBO traits for different types
    72→TEST_F(SBOTest, SBOTraitsBasicTypes) {
    73→    // Small built-in types should be SBO eligible
    74→    EXPECT_TRUE(SBOTraits<int>::is_sbo_eligible);
    75→    EXPECT_TRUE(SBOTraits<int>::always_sbo);
    76→    EXPECT_FALSE(SBOTraits<int>::conditional_sbo);
    77→
    78→    EXPECT_TRUE(SBOTraits<double>::is_sbo_eligible);
    79→    EXPECT_TRUE(SBOTraits<double>::always_sbo);
    80→
    81→    // Small structs should be SBO eligible
    82→    EXPECT_TRUE(SBOTraits<SmallStruct>::is_sbo_eligible);
    83→    EXPECT_TRUE(SBOTraits<SmallStruct>::always_sbo);
    84→
    85→    // Medium structs should be conditionally SBO eligible
    86→    EXPECT_TRUE(SBOTraits<MediumStruct>::is_sbo_eligible);
    87→    EXPECT_FALSE(SBOTraits<MediumStruct>::always_sbo);
    88→    EXPECT_TRUE(SBOTraits<MediumStruct>::conditional_sbo);
    89→
    90→    // Large structs should not be SBO eligible
    91→    EXPECT_FALSE(SBOTraits<LargeStruct>::is_sbo_eligible);
    92→    EXPECT_TRUE(SBOTraits<LargeStruct>::force_heap);
    93→
    94→    // Standard library containers should be forced to heap
    95→    EXPECT_TRUE(SBOTraits<std::string>::force_heap);
    96→    EXPECT_TRUE(SBOTraits<std::vector<int>>::force_heap);
    97→}
