    19→// Test data structures for SBO testing
    20→struct SmallStruct {
    21→    int x, y;
    22→    SmallStruct(int x = 0, int y = 0) : x(x), y(y) {}
    23→    bool operator==(const SmallStruct& other) const {
    24→        return x == other.x && y == other.y;
    25→    }
    26→    bool operator!=(const SmallStruct& other) const {
    27→        return !(*this == other);
    28→    }
    29→};
    30→
    31→struct MediumStruct {
    32→    double data[4];  // 32 bytes
    33→    MediumStruct(double val = 0.0) {
    34→        for (int i = 0; i < 4; ++i) data[i] = val + i;
    35→    }
    36→    bool operator==(const MediumStruct& other) const {
    37→        for (int i = 0; i < 4; ++i) {
    38→            if (data[i] != other.data[i]) return false;
    39→        }
    40→        return true;
    41→    }
    42→    bool operator!=(const MediumStruct& other) const {
    43→        return !(*this == other);
    44→    }
    45→};
    46→
    47→struct LargeStruct {
    48→    char data[128];  // 128 bytes - should force heap allocation
    49→    LargeStruct(char fill = 'A') {
    50→        std::fill(data, data + 128, fill);
    51→    }
    52→    bool operator==(const LargeStruct& other) const {
    53→        return std::memcmp(data, other.data, 128) == 0;
    54→    }
    55→    bool operator!=(const LargeStruct& other) const {
    56→        return !(*this == other);
    57→    }
    58→};
