    56→TEST(ResetConsistencyTest, ResetWithMultipleDependenciesPartialFailure) {
    57→    auto a = reaction::var(1);
    58→    auto b = reaction::var(2);
    59→
    60→    // Create two calculations
    61→    auto calc1 = reaction::calc([](int x) { return x * 2; }, a);
    62→    auto calc2 = reaction::calc([](int y) { return y + 1; }, b);
    63→
    64→    // Make calc1 depend on calc2
    65→    calc1.reset([&]() { return calc2() * 2; });
    66→    EXPECT_EQ(calc1.get(), 6); // (2+1) * 2 = 6
    67→
    68→    // Now attempt to make calc2 depend on calc1, creating a cycle
    69→    EXPECT_THROW(calc2.reset([&]() { return calc1() + 1; }), std::runtime_error);
    70→
    71→    // Verify calc2 is still in a consistent state
    72→    EXPECT_EQ(calc2.get(), 3); // b(2) + 1 = 3
    73→
    74→    // Verify calc2's dependencies are still intact
    75→    b.value(10);
    76→    EXPECT_EQ(calc2.get(), 11); // 10 + 1
