    33→ * @brief Small Buffer Optimized Resource storage.
    34→ *
    35→ * This class provides automatic stack/heap allocation based on type size and runtime conditions.
    36→ * Small objects are stored inline to avoid heap allocation overhead.
    37→ *
    38→ * @tparam Type The type of resource to store.
    39→ */
    40→template<typename Type>
    41→class SBOResource : public ObserverNode {
    42→private:
    43→    // Storage decision logic
    44→    static constexpr bool always_sbo = SBOTraits<Type>::always_sbo;
    45→    static constexpr bool conditional_sbo = SBOTraits<Type>::conditional_sbo;
    46→    static constexpr bool force_heap = SBOTraits<Type>::force_heap;
    47→
    48→    // Union for storage flexibility
    49→    union Storage {
    50→        alignas(Type) char buffer[sizeof(Type)];  // Stack storage
    51→        std::unique_ptr<Type> heap_ptr;           // Heap storage
    52→
    53→        Storage() noexcept {} // No initialization - manual lifetime management
    54→        ~Storage() noexcept {} // Manual lifetime management
    55→    } storage;
    56→
    57→    bool is_sbo_storage;  // Track which storage is active
    58→    bool is_initialized;  // Track initialization state
    59→
    60→public:
    61→    /**
    62→     * @brief Default constructor with null state.
    63→     */
    64→    SBOResource() : is_sbo_storage(false), is_initialized(false) {
    65→        // Initialize heap_ptr explicitly
    66→        new(&storage.heap_ptr) std::unique_ptr<Type>(nullptr);
    67→    }
    68→
    69→    /**
    70→     * @brief Constructor with forwarded arguments.
    71→     */
    72→    template<typename T>
    73→        requires(!std::is_same_v<std::remove_cvref_t<T>, SBOResource<Type>>)
    74→    SBOResource(T&& t) {
    75→        // Determine storage strategy first
    76→        if constexpr (SBOTraits<Type>::always_sbo) {
    77→            // Always use SBO - no heap_ptr needed
    78→            new(storage.buffer) Type(std::forward<T>(t));
    79→            is_sbo_storage = true;
    80→            is_initialized = true;
    81→        } else if constexpr (SBOTraits<Type>::conditional_sbo) {
    82→            // Conditional SBO based on stack usage
    83→            StackMonitor::StackGuard<sizeof(Type)> guard;
    84→            if (guard.success()) {
    85→                // Use SBO
    86→                new(storage.buffer) Type(std::forward<T>(t));
    87→                is_sbo_storage = true;
    88→                is_initialized = true;
    89→            } else {
    90→                // Use heap allocation
    91→                new(&storage.heap_ptr) std::unique_ptr<Type>(std::make_unique<Type>(std::forward<T>(t)));
    92→                is_sbo_storage = false;
    93→                is_initialized = true;
    94→            }
