    14→namespace reaction::memory {
    15→
    16→/**
    17→ * @brief Thread-local stack usage monitor for SBO safety.
    18→ *
    19→ * This class tracks the amount of stack memory used by SBO allocations
    20→ * to prevent stack overflow. Each thread maintains its own usage counter.
    21→ */
    22→class StackMonitor {
    23→private:
    24→    thread_local static std::atomic<size_t> current_usage;
    25→    thread_local static bool monitoring_enabled;
    26→
    27→public:
    28→    /**
    29→     * @brief Initialize stack monitoring for current thread.
    30→     */
    31→    static void initialize() noexcept {
    32→        current_usage.store(0, std::memory_order_relaxed);
    33→        monitoring_enabled = true;
    34→    }
    35→
    36→    /**
    37→     * @brief Get current stack usage by SBO allocations.
    38→     */
    39→    static size_t getCurrentUsage() noexcept {
    40→        return current_usage.load(std::memory_order_relaxed);
    41→    }
    42→
    43→    /**
    44→     * @brief Check if we can safely allocate the given size on stack.
    45→     */
    46→    template<size_t Size>
    47→    static bool canAllocate() noexcept {
    48→        if (!monitoring_enabled) {
    49→            return Size <= SBOConfig::CONDITIONAL_SBO_SIZE;
    50→        }
    51→
    52→        size_t current = current_usage.load(std::memory_order_relaxed);
    53→        return (current + Size) <= SBOConfig::MAX_SBO_STACK_USAGE;
    54→    }
    55→
    56→    /**
    57→     * @brief Check if we can safely allocate the given size on stack (runtime version).
    58→     */
    59→    static bool canAllocate(size_t size) noexcept {
    60→        if (!monitoring_enabled) {
    61→            return size <= SBOConfig::CONDITIONAL_SBO_SIZE;
    62→        }
    63→
    64→        size_t current = current_usage.load(std::memory_order_relaxed);
    65→        return (current + size) <= SBOConfig::MAX_SBO_STACK_USAGE;
    66→    }
    67→
    68→    /**
    69→     * @brief RAII guard for stack usage tracking.
    70→     *
    71→     * Automatically increments usage on construction and decrements on destruction.
    72→     * Reports whether the allocation was successful.
    73→     */
    74→    template<size_t Size>
    75→    class StackGuard {
    76→    private:
    77→        bool allocated;
    78→
    79→    public:
    80→        StackGuard() noexcept : allocated(false) {
    81→            if (canAllocate<Size>()) {
    82→                current_usage.fetch_add(Size, std::memory_order_relaxed);
    83→                allocated = true;
    84→            }
    85→        }
    86→
    87→        explicit StackGuard(size_t size) noexcept : allocated(false) {
    88→            if (canAllocate(size)) {
    89→                current_usage.fetch_add(size, std::memory_order_relaxed);
    90→                allocated = true;
    91→            }
    92→        }
    93→
    94→        ~StackGuard() noexcept {
    95→            if (allocated) {
    96→                current_usage.fetch_sub(Size, std::memory_order_relaxed);
    97→            }
    98→        }
    99→
   100→        // Non-copyable, non-movable
   101→        StackGuard(const StackGuard&) = delete;
   102→        StackGuard& operator=(const StackGuard&) = delete;
   103→        StackGuard(StackGuard&&) = delete;
   104→        StackGuard& operator=(StackGuard&&) = delete;
   105→
   106→        /**
   107→         * @brief Check if the stack allocation was successful.
   108→         */
   109→        bool success() const noexcept {
   110→            return allocated;
   111→        }
   112→
   113→        /**
   114→         * @brief Explicit conversion to bool for convenience.
   115→         */
   116→        explicit operator bool() const noexcept {
   117→            return allocated;
   118→        }
   119→    };
   120→
   121→    /**
   122→     * @brief Get usage statistics for debugging.
   123→     */
   124→    struct UsageStats {
   125→        size_t current_usage;
   126→        size_t max_allowed;
   127→        double usage_percentage;
   128→        bool near_limit;
   129→    };
   130→
   131→    static UsageStats getStats() noexcept {
   132→        size_t current = current_usage.load(std::memory_order_relaxed);
   133→        size_t max_allowed = SBOConfig::MAX_SBO_STACK_USAGE;
   134→        double percentage = (static_cast<double>(current) / max_allowed) * 100.0;
   135→        bool near_limit = current >= SBOConfig::STACK_USAGE_WARNING;
   136→
   137→        return UsageStats{
   138→            .current_usage = current,
   139→            .max_allowed = max_allowed,
   140→            .usage_percentage = percentage,
   141→            .near_limit = near_limit
   142→        };
