   600→/**
   601→ * @brief Test reset operation invalidation in multi-threaded environment
   602→ *
   603→ * This test checks if reset operations properly invalidate dependent expressions
   604→ * in a concurrent setting.
   605→ */
   606→TEST(ThreadSafetyTest, ResetInvalidationConcurrency) {
   607→    std::cout << "=== Reset Invalidation Concurrency Test ===" << std::endl;
   608→
   609→    auto &manager = reaction::ThreadManager::getInstance();
   610→    manager.resetForTesting();
   611→
   612→    std::atomic<bool> resetCompleted{false};
   613→    std::atomic<int> readCount{0};
   614→    std::atomic<int> invalidationErrors{0};
   615→
   616→    // Create a simple dependency chain: var -> expr -> dependent_expr
   617→    auto sharedVar = reaction::var(10);
   618→    auto sharedExpr = reaction::calc([&]() {
   619→        return sharedVar() * 2;
   620→    });
   621→    auto dependentExpr = reaction::calc([&]() {
   622→        return sharedExpr() * 3;
   623→    });
   624→
   625→    // Initial state: expr should be 20, dependent should be 60
   626→    EXPECT_EQ(sharedExpr.get(), 20);
   627→    EXPECT_EQ(dependentExpr.get(), 60);
   628→
   629→    // Thread 1: Reset the variable and expression
   630→    std::thread resetThread([&]() {
   631→        std::cout << "Reset thread: Changing var to 20" << std::endl;
   632→        sharedVar.value(20);
   633→
   634→        std::cout << "Reset thread: Before reset, expr=" << sharedExpr.get() << ", dependent=" << dependentExpr.get() << std::endl;
   635→
   636→        // Reset expression
   637→        sharedExpr.reset([&]() {
   638→            return sharedVar.get() * 3;
   639→        });
   640→
   641→        std::cout << "Reset thread: After reset, expr=" << sharedExpr.get() << ", dependent=" << dependentExpr.get() << std::endl;
   642→        resetCompleted = true;
   643→    });
   644→
   645→    // Thread 2: Continuously read the expressions and check consistency
   646→    std::thread readThread([&]() {
   647→        while (!resetCompleted.load()) {
   648→            int varValue = sharedVar.get();
   649→            int exprValue = sharedExpr.get();
   650→            int dependentValue = dependentExpr.get();
   651→
   652→            // Before reset: expr should be var * 2, dependent should be expr * 3
   653→            // After reset: expr should be var * 3, dependent should be expr * 3
   654→            if (varValue == 10 && exprValue != 20) {
   655→                invalidationErrors++;
   656→                std::cout << "Invalidation error before reset: var=" << varValue
   657→                          << ", expr=" << exprValue << " (expected 20)" << std::endl;
   658→            } else if (varValue == 20 && exprValue != 60) {
   659→                invalidationErrors++;
   660→                std::cout << "Invalidation error after reset: var=" << varValue
   661→                          << ", expr=" << exprValue << " (expected 60)" << std::endl;
   662→            } else if (varValue == 20 && exprValue == 60 && dependentValue != 180) {
   663→                invalidationErrors++;
   664→                std::cout << "Dependent invalidation error: var=" << varValue
   665→                          << ", expr=" << exprValue << ", dependent=" << dependentValue << " (expected 180)" << std::endl;
   666→            }
   667→
   668→            readCount++;
   669→            std::this_thread::sleep_for(std::chrono::microseconds(100));
   670→        }
   671→
   672→        // Final check after reset
   673→        int finalVarValue = sharedVar.get();
   674→        int finalExprValue = sharedExpr.get();
   675→        int finalDependentValue = dependentExpr.get();
   676→
   677→        if (finalVarValue == 20 && finalExprValue == 60 && finalDependentValue != 180) {
   678→            invalidationErrors++;
   679→            std::cout << "Final invalidation error: var=" << finalVarValue
   680→                      << ", expr=" << finalExprValue << ", dependent=" << finalDependentValue << " (expected 180)" << std::endl;
   681→        }
   682→    });
   683→
   684→    resetThread.join();
   685→    readThread.join();
   686→
   687→    std::cout << "=== Reset Invalidation Concurrency Test Results ===" << std::endl;
   688→    std::cout << "Read operations: " << readCount.load() << std::endl;
   689→    std::cout << "Invalidation errors: " << invalidationErrors.load() << std::endl;
   690→
   691→    // Final state should be correct
   692→    EXPECT_EQ(sharedVar.get(), 20);
   693→    EXPECT_EQ(sharedExpr.get(), 60);
   694→    EXPECT_EQ(dependentExpr.get(), 180);
   695→
   696→    std::cout << "✅ Reset invalidation concurrency test completed" << std::endl;
   697→}
