   191→// === Conditional Mutex Abstractions with Template Optimization ===
   192→
   193→/**
   194→ * @brief Unified conditional mutex wrapper with template specialization.
   195→ *
   196→ * This template automatically adapts between thread-safe and single-threaded modes
   197→ * with compile-time optimization for better performance.
   198→ *
   199→ * @tparam MutexType The underlying mutex type (std::mutex, std::shared_mutex, etc.)
   200→ */
   201→template <typename MutexType>
   202→class ConditionalMutexWrapper {
   203→public:
   204→    /// @brief Acquire lock if thread safety is enabled.
   205→    void lock() noexcept(noexcept(std::declval<MutexType>().lock())) {
   206→        if (ThreadManager::getInstance().isThreadSafetyEnabled()) [[likely]] {
   207→            m_mutex.lock();
   208→        }
   209→    }
   210→
   211→    /// @brief Release lock if thread safety is enabled.
   212→    void unlock() noexcept(noexcept(std::declval<MutexType>().unlock())) {
   213→        if (ThreadManager::getInstance().isThreadSafetyEnabled()) [[likely]] {
   214→            m_mutex.unlock();
   215→        }
   216→    }
   217→
   218→    /// @brief Try to acquire lock if thread safety is enabled.
   219→    [[nodiscard]] bool try_lock() noexcept(noexcept(std::declval<MutexType>().try_lock())) {
   220→        if (ThreadManager::getInstance().isThreadSafetyEnabled()) [[likely]] {
   221→            return m_mutex.try_lock();
   222→        }
   223→        return true; // Always succeed when thread safety is disabled
   224→    }
   225→
   226→    // Shared mutex operations (SFINAE-enabled for types that support them)
   227→    template <typename T = MutexType>
   228→    auto lock_shared() noexcept(noexcept(std::declval<T>().lock_shared()))
   229→        -> decltype(std::declval<T>().lock_shared(), void()) {
   230→        if (ThreadManager::getInstance().isThreadSafetyEnabled()) [[likely]] {
   231→            m_mutex.lock_shared();
   232→        }
   233→    }
   234→
   235→    template <typename T = MutexType>
   236→    auto unlock_shared() noexcept(noexcept(std::declval<T>().unlock_shared()))
   237→        -> decltype(std::declval<T>().unlock_shared(), void()) {
   238→        if (ThreadManager::getInstance().isThreadSafetyEnabled()) [[likely]] {
   239→            m_mutex.unlock_shared();
   240→        }
   241→    }
   242→
   243→    template <typename T = MutexType>
   244→    auto try_lock_shared() noexcept(noexcept(std::declval<T>().try_lock_shared()))
   245→        -> decltype(std::declval<T>().try_lock_shared()) {
   246→        if (ThreadManager::getInstance().isThreadSafetyEnabled()) [[likely]] {
   247→            return m_mutex.try_lock_shared();
   248→        }
   249→        return true; // Always succeed when thread safety is disabled
   250→    }
   251→
   252→private:
   253→    MutexType m_mutex;
   254→};
   255→
   256→/**
   257→ * @brief Conditional shared mutex that provides no-op when thread safety is disabled.
   258→ */
   259→using ConditionalSharedMutex = ConditionalMutexWrapper<std::shared_mutex>;
   260→
   261→/**
   262→ * @brief Conditional mutex that provides no-op when thread safety is disabled.
   263→ */
   264→using ConditionalMutex = ConditionalMutexWrapper<std::mutex>;
   265→
   266→// === Optimized Lock Guard Abstractions ===
   267→
   268→/**
   269→ * @brief Template-based RAII lock guard generator.
   270→ *
   271→ * @param GuardName The name of the guard class
   272→ * @param LockMethod The locking method name
   273→ * @param UnlockMethod The unlocking method name
   274→ */
   275→#define REACTION_DEFINE_LOCK_GUARD(GuardName, LockMethod, UnlockMethod)         \
   276→    template <typename Mutex>                                                   \
   277→    class GuardName {                                                           \
   278→    public:                                                                     \
   279→        explicit GuardName(Mutex &mutex) noexcept(noexcept(mutex.LockMethod())) \
   280→            : m_mutex(mutex) {                                                  \
   281→            m_mutex.LockMethod();                                               \
   282→        }                                                                       \
   283→                                                                                \
   284→        ~GuardName() noexcept(noexcept(m_mutex.UnlockMethod())) {               \
   285→            m_mutex.UnlockMethod();                                             \
   286→        }                                                                       \
   287→                                                                                \
   288→        GuardName(const GuardName &) = delete;                                  \
   289→        GuardName &operator=(const GuardName &) = delete;                       \
   290→        GuardName(GuardName &&) = delete;                                       \
   291→        GuardName &operator=(GuardName &&) = delete;                            \
   292→                                                                                \
   293→    private:                                                                    \
   294→        Mutex &m_mutex;                                                         \
   295→    }
   296→
   297→// Generate optimized lock guards
   298→REACTION_DEFINE_LOCK_GUARD(ConditionalLockGuard, lock, unlock);
   299→REACTION_DEFINE_LOCK_GUARD(ConditionalSharedLockGuard, lock_shared, unlock_shared);
   300→
   301→/**
   302→ * @brief RAII shared lock guard for conditional shared mutex.
   303→ */
   304→template <typename Mutex>
   305→using ConditionalSharedLock = ConditionalSharedLockGuard<Mutex>;
   306→
   307→/**
   308→ * @brief RAII unique lock guard for conditional mutex.
   309→ */
   310→template <typename Mutex>
   311→using ConditionalUniqueLock = ConditionalLockGuard<Mutex>;
   312→
   313→// Helper macros for thread registration with better performance
   314→#define REACTION_REGISTER_THREAD()                                                        \
   315→    do {                                                                                  \
   316→        static thread_local reaction::ThreadRegistrationGuard thread_guard_##__COUNTER__; \
   317→        (void)thread_guard_##__COUNTER__;                                                 \
   318→    } while (0)
   319→
   320→// Cleanup macro to avoid pollution
   321→#undef REACTION_DEFINE_LOCK_GUARD
   322→
   323→} // namespace reaction
